from typing import Union, Any

from taf.vran.vdu.enb.rest.exceptions import ReleaseNotSupported
from taf.vran.vdu.enb.rest.releases.ltevdu25r3 import LTEvDU25R3
from taf.vran.vdu.enb.rest.releases.ltevdu26r1 import LTEvDU26R1
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails


class ReleaseProvider:
    _supported_releases = {
        "25r3": LTEvDU25R3,
        "26r1": LTEvDU26R1
    }

    LATEST_RELEASE = "26r1"

    @classmethod
    def get_release(
        cls,
        host: str,
        port: str,
        username: str,
        password: str,
        release: Union[str, None],
        secure: bool,
        timeout: float,
        connection_name: str,
        read_only: bool,
        update_expired_password: bool
    ) -> Any:
        """
        Returns an instance of the appropriate release class

        :param host: Hostname or IP address, for example: "192.168.255.129"
        :param port: Port number, for example: "443
        :param username: Username, for example: "Nemuadmin"
        :param password: Password, for example: "nemuuser"
        :param release: SW release, for example "25r3". If None, the latest release will be used.
        :param secure: Use HTTPS or HTTP. True for HTTPS, False for HTTP
        :param timeout: Timeout for the REST API requests
        :param connection_name: Name of the connection, for example "default"
        :param read_only: If True, the connection will be in read-only mode
        :param update_expired_password: If True, the client will try to update expired password automatically

        :raises ReleaseNotSupported: If given release is not supported

        :returns: Instance of the appropriate release class
        """
        if release is None:
            release = cls.LATEST_RELEASE

        lte_vdu = cls._supported_releases.get(release)
        if not lte_vdu:
            raise ReleaseNotSupported(release=release)

        connection_details = ConnectionDetails(
            host=host,
            port=port,
            username=username,
            password=password,
            secure=secure,
            timeout=timeout,
            connection_name=connection_name,
            read_only=read_only,
            update_expired_password=update_expired_password
        )

        return lte_vdu(connection_details=connection_details)
